INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "邵延钧", "aliases": ["邵延鈞"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "后蜀工部尚书、判武德军。952年对监押王承丕不够礼敬，王承丕谋乱，命人杀邵延钧并屠其家。出生年未载，死亡年952年。", "biography": null, "status": "draft", "id": "5060776e-db67-5372-b997-da1b05c11d64"}, {"name": "王承丕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "后蜀武德军监押。952年杀邵延钧，自称奉诏处置军府，开库赏兵、释放囚犯。孙钦发现他谋反后率兵捕杀，并将首级送往成都。出生年未载。", "biography": null, "status": "draft", "id": "52ab9afa-7212-51c6-bdca-19fd3c84a2bd"}, {"name": "孙钦", "aliases": ["孫欽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安次人，后蜀左奉圣都指挥使。952年原拟率部戍边，受王承丕邀入军府时不知道其谋乱。得知无诏后脱身，回营率兵捕杀王承丕。生卒年未载。", "biography": null, "status": "draft", "id": "1e91b29c-d8a8-5ae5-ab85-2882c26ab7cd"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵季札", "aliases": ["趙季札"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。952年受孟昶之命赴梓州，慰抚吏民。生卒年未载。", "biography": null, "status": "draft", "id": "faffdaed-5d02-5666-a551-64c61d7f86a3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

